function estimate = v4PaperLocalResidualEstimate(compensatedMidamble,c,maxRateBinsPerSec)
%V4PAPERLOCALRESIDUALESTIMATE Physically bounded Midamble residual search.
physicalGapSymbols = c.paperMidambleInterval+1;
halfWidthBins = ceil(maxRateBinsPerSec*physicalGapSymbols*c.symbolDurationSec);
candidates = (-halfWidthBins:0.5:halfWidthBins).';
coarse = v4PaperIntegerPointEstimate(compensatedMidamble,0,c);
refined = v4PhaseRotationEstimate(compensatedMidamble,0,c,candidates);
estimate = struct('offsetBins',refined.offsetBins, ...
    'phaseRad',refined.phaseRad,'peakMetric',refined.peakMetric, ...
    'peakRatio',refined.peakRatio,'peakAtBoundary',refined.peakAtBoundary, ...
    'globalFftPeakRatio',coarse.peakRatio, ...
    'searchHalfWidthBins',halfWidthBins,'resolutionBins',0.5, ...
    'usesPayloadTruth',false,'usesOrbitTruth',false);
end
